"""Application module that currently loads config inline.

The task is to migrate this to use a proper config_loader module.
"""

import json
from pathlib import Path


def load_settings(config_path: str) -> dict:
    """Load settings from a JSON file.

    Currently does basic loading without proper error handling.
    The config_loader task should improve this.
    """
    path = Path(config_path)
    if not path.exists():
        return {}  # Silent fallback — this is what the task should fix
    text = path.read_text(encoding="utf-8")
    return json.loads(text)


def get_database_url(settings: dict) -> str:
    """Get the database URL from settings."""
    return settings.get("database_url", "sqlite:///default.db")


def get_app_name(settings: dict) -> str:
    """Get the application name from settings."""
    return settings.get("app_name", "SampleApp")


def get_port(settings: dict) -> int:
    """Get the server port from settings."""
    return settings.get("port", 8000)

